('lib/content/gpx_scolarite/dps_dpg/generalite_pages/libertés_publiques/introduction/declaration_droits_homme_page.dart','f00004','Informations générales',4,'TextSpan','Elle figure aujourd’hui dans le Préambule de la Constitution de 1958','Elle figure aujourd’hui dans le Préambule de la Constitution de 1958','{"font_weight_hints":["FontWeight.w700"]}'::jsonb,true),
